"""Exporta dois relatórios PDF a partir das evidências locais.

Execução portátil: python scripts/export_reports.py [--render]
Requer reportlab e pypdf; --render requer pypdfium2 e Pillow.
Fontes Helvetica/Helvetica-Bold internas do PDF: nenhum arquivo de fonte local.
Não altera os relatórios Markdown nem os artefatos de treinamento.
"""
import argparse
from pathlib import Path
import hashlib
import json
from xml.sax.saxutils import escape
from reportlab.lib import colors
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import ParagraphStyle, getSampleStyleSheet
from reportlab.lib.units import mm
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, PageBreak, Image
from pypdf import PdfReader

ROOT = Path(__file__).resolve().parents[1]
INK = colors.HexColor("#152F42")
TEAL = colors.HexColor("#087F8C")
PALE = colors.HexColor("#EAF3F5")
GRAY = colors.HexColor("#516573")
STYLES = getSampleStyleSheet()
STYLES.add(ParagraphStyle(name="ReportTitle", fontName="Helvetica-Bold", fontSize=25, leading=29, textColor=INK, spaceAfter=12))
STYLES.add(ParagraphStyle(name="SectionTitle", fontName="Helvetica-Bold", fontSize=15, leading=19, textColor=TEAL, spaceBefore=11, spaceAfter=9, keepWithNext=True))
STYLES.add(ParagraphStyle(name="ReportBody", fontName="Helvetica", fontSize=10.5, leading=15, textColor=INK, spaceAfter=9))
STYLES.add(ParagraphStyle(name="ReportSmall", fontName="Helvetica", fontSize=9, leading=12, textColor=GRAY, spaceAfter=6))
STYLES.add(ParagraphStyle(name="TableBody", fontName="Helvetica", fontSize=9.4, leading=12.5, textColor=INK))
STYLES.add(ParagraphStyle(name="TableHead", fontName="Helvetica-Bold", fontSize=9.4, leading=12.5, textColor=colors.white))

def clean(value):
    return str(value).replace("−", "-").replace("–", "-").replace("—", "-").replace("×", "x").replace("≤", "<=").replace("≥", ">=").replace("\u2011", "-")

def p(text, style="ReportBody"):
    return Paragraph(clean(text), STYLES[style])

def br(value, digits=2):
    return f"{value:,.{digits}f}".replace(",", "_").replace(".", ",").replace("_", ".")

def pct(value):
    return br(value * 100) + "%"

def table(headers, rows, widths=None):
    data = [[p(escape(h), "TableHead") for h in headers]]
    data += [[p(escape(clean(c)).replace("\n", "<br/>"), "TableBody") for c in row] for row in rows]
    result = Table(data, colWidths=widths, repeatRows=1, hAlign="LEFT")
    result.setStyle(TableStyle([("BACKGROUND", (0, 0), (-1, 0), TEAL), ("VALIGN", (0, 0), (-1, -1), "TOP"), ("ROWBACKGROUNDS", (0, 1), (-1, -1), [colors.white, PALE]), ("LEFTPADDING", (0, 0), (-1, -1), 9), ("RIGHTPADDING", (0, 0), (-1, -1), 9), ("TOPPADDING", (0, 0), (-1, -1), 8), ("BOTTOMPADDING", (0, 0), (-1, -1), 8), ("LINEBELOW", (0, -1), (-1, -1), .5, colors.HexColor("#C9DADF"))]))
    return result

def header(title, subtitle):
    return [p("PROJETO FRETES | NUTRIÇÃO ANIMAL", "ReportSmall"), p(title, "ReportTitle"), p(subtitle, "ReportSmall"), Spacer(1, 4 * mm)]

def section(title):
    return p(title, "SectionTitle")

def note(text):
    return table(["Leitura para decisão"], [[text]], [171 * mm])

def foot(canvas, doc):
    canvas.saveState()
    canvas.setStrokeColor(TEAL)
    canvas.setLineWidth(.7)
    canvas.line(20 * mm, 17 * mm, 191 * mm, 17 * mm)
    canvas.setFont("Helvetica", 8)
    canvas.setFillColor(GRAY)
    canvas.drawString(20 * mm, 12 * mm, "Projeto acadêmico de fretes | Evidências da versão em desenvolvimento")
    canvas.drawRightString(191 * mm, 12 * mm, str(doc.page))
    canvas.restoreState()

def load(relative):
    return json.loads((ROOT / relative).read_text(encoding="utf-8"))

def metric_rows(summary, common=False):
    scores = summary["common_sample_test" if common else "test"]
    rows = []
    for name, key, formatter in [("MAE (R$/t)", "MAE_rs_t", br), ("RMSE (R$/t)", "RMSE_rs_t", br), ("WAPE de tarifa", "WAPE_tarifa", pct), ("WAPE de custo", "WAPE_custo", pct), ("Viés do gasto", "vies_total_custo", pct)]:
        rows.append([name, formatter(scores[0][key]), formatter(scores[1][key])])
    return rows

def image(relative, width=171 * mm):
    path = ROOT / relative
    if not path.exists():
        return p("Figura não disponível nesta fotografia de execução.", "ReportSmall")
    from reportlab.lib.utils import ImageReader
    w, h = ImageReader(str(path)).getSize()
    return Image(str(path), width=width, height=width * h / w)

