    story += header("5. Resultados e interpretação", "Manter erro absoluto e viés agregado visíveis")
    story += [table(["Teste completo", "Referência imputada", "RF atual"], metric_rows(model), [66 * mm, 55 * mm, 50 * mm]), p("MAE: erro absoluto médio em R$/t. WAPE de tarifa: soma de erros absolutos de tarifa / soma das tarifas reais. WAPE de custo: soma de erros absolutos ponderados pela tonelagem / custo real. Viés: (custo previsto - custo real) / custo real. R² no teste: 0,336 para referência e 0,468 para RF."), section("Comparação com cobertura comum"), table(["5.294 itens com orçamento", "Referência observada", "RF atual"], [["MAE R$/t", "58,74", "52,14"], ["WAPE tarifa", "25,99%", "23,07%"], ["Viés de custo", "-4,59%", "-14,05%"]], [66 * mm, 55 * mm, 50 * mm]), p("A comparação completa imputa 1.033 referências ausentes com mediana calculada no treino. A amostra comum permite comparação sem cobertura desigual. A melhora de MAE é de aproximadamente 11,2% na amostra comum, menor que na comparação imputada."), image("reports/figures/diagnostico_residuos.png", 155 * mm), p("Os resíduos possuem cauda positiva elevada. A importância por permutação usa até 1.500 itens do teste, três repetições e semente 42; mede contribuição preditiva, sem demonstrar causalidade. Variáveis correlacionadas podem dividir importância.", "ReportSmall"), p("O resultado atende parcialmente ao critério preditivo, mas não comprova adequação ao orçamento: o viés agregado negativo permanece relevante. Não foi aplicada correção usando o teste conhecido.", "ReportSmall"), PageBreak()]
